int tcp_disconnect(struct sock *sk, int flags)
{
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
        case TCP_LISTEN:
            /* Stop listening and reset backlog */
            sk->sk_max_ack backlog = 0;
            break;
        case TCP_SYN_SENT:
        case TCP_SYN_RECV:
            /* Send a reset if needed */
            tcp_send_reset(sk);
            break;
        default:
            if (sk->sk_state != TCP_CLOSE_WAIT) {
                tcp_send_reset(sk);
            }
            break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    /* Purge transmit and receive queues */
    skb_queue_purge(&sk->sk_write_queue);
    skb_queue_purge(&sk->sk_receive_queue);

    /* Reset TCP parameters */
    sk->sk_wmem_queued = 0;
    sk->sk_rmem_queued = 0;
