    sk->sk_rcv_wnd = 0;
    sk->sk_snd_wnd = 0;
    sk->sk_rcv_wnd_max = 0;
    sk->sk_snd_wnd_max = 0;
    sk->sk_last_ack_sent = 0;
    sk->sk_ts_recent = 0;
    sk->sk_ts_recent_stamp = 0;
