int tcp_disconnect(struct sock *sk, int flags) {
    int err = 0;

    lock_sock(sk);

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
            case TCP_LISTEN:
                tcp_stop_listening(sk);
                break;
            case TCP_ESTABLISHED:
            case TCP_FIN_WAIT1:
            case TCP_FIN_WAIT2:
            case TCP_CLOSE_WAIT:
            case TCP_CLOSING:
            case TCP_LAST_ACK:
                if (tcp_send_reset(sk)) {
                    err = -1;
                }
                break;
            default:
                break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    tcp_purge_transmit_queue(sk);
