int tcp_disconnect(struct sock *sk, int flags)
{
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
        case TCP_LISTEN:
            /* Stop listening */
            tcp_stop_listen(sk);
            break;
        case TCP_SYN_SENT:
        case TCP_SYN_RECV:
        case TCP_ESTABLISHED:
        case TCP_FIN_WAIT1:
        case TCP_FIN_WAIT2:
        case TCP_CLOSE_WAIT:
        case TCP_CLOSING:
        case TCP_LAST_ACK:
            /* Send reset if needed */
            if (sk->sk_state != TCP_CLOSING || (sk->sk_flags & TCP_RST_SENT))
                tcp_send_reset(sk);
            break;
        }

        /* Set state to TCP_CLOSE */
        sk->sk_state = TCP_CLOSE;
    }

    /* Purge transmit and receive queues */
    skb_queue_purge(&sk->sk_write_queue);
    skb_queue_purge(&sk->sk_receive_queue);

    /* Reset TCP parameters */
    sk->sk_rcv_mss = 0;
    sk->sk_data_queue_len = 0;
    sk->sk_data_bytes = 0;
    sk->sk_wmem_alloc = 0;
    sk->sk_rmem_alloc = 0;

    /* Clean up fastopen-related fields */
    sk->sk_fastopen_info = NULL;

    return err;
}

int tcp_disconnect(struct sock *sk, int flags) {
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
            case TCP_LISTEN:
                tcp_stop_listening(sk);
                break;
            case TCP_SYN_SENT:
            case TCP_SYN_RECV:
            case TCP_ESTABLISHED:
                if (sk->sk_state != TCP_CLOSE && !(flags & TCP_CLOSE_RESET))
                    tcp_send_reset(sk);
                break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    tcp_purge_tx_queue(sk);
    tcp_purge_rx_queue(sk);

    sk->sk_wmem_queued = 0;
    sk->sk_forward_alloc = 0;
    sk->sk_rmem_queued = 0;
    sk->sk_rcvlowat = 0;
    sk->sk_rcvbuf = 0;
    sk->sk_wnd = 0;
    sk->sk_wnd_clamp = 0;
    sk->sk_sndbuf = 0;
    sk->sk_userlocks = 0;
    sk->sk_data_ready(sk, 0);

    sk->sk_rcv_mss = TCP_MSS_DEFAULT;

    tcp_fastopen_cleanup(sk);

    if (sk->sk_err) {
        err = sk->sk_err;
        sk->sk_err = 0;
    }

    return err;
}

int tcp_disconnect(struct sock *sk, int flags) {
    int err = 0;

    if (sk->sk_state != TCP_CLOSE) {
        switch (sk->sk_state) {
            case TCP_LISTEN:
                tcp_stop_listen(sk);
                break;
            case TCP_SYN_SENT:
            case TCP_SYN_RECV:
                // Send a reset if needed
                if (tcp_send_reset(sk) < 0) {
                    err = -1;
                }
                break;
            default:
                break;
        }

        sk->sk_state = TCP_CLOSE;
    }

    // Purge transmit and receive queues
    skb_queue_purge(&sk->sk_write_queue);
    skb_queue_purge(&sk->sk_receive_queue);

    // Reset TCP parameters
    tcp_reset(sk);

    // Initialize receive MSS
    sk->sk_rcv_mss = TCP_DEFAULT_MSS;

    // Clean up fastopen-related fields
    tcp_fastopen_cleanup(sk);

    return err;
}
